<div class="section-heading"><div><h2>Project pages</h2><p class="muted">Capture ideas and decisions, then turn them into linked work items.</p></div><a class="btn" href="#work-new-page">+ Page</a></div><?php if(!$pages): ?><section class="card empty"><h3>A place for the thinking behind the work.</h3><p>Create a project page. Every save keeps its previous version.</p></section><?php else: ?><div class="website-grid"><?php foreach($pages as $projectPage): ?><article class="card"><span class="website-kicker"><?= $projectPage['pinned']?'PINNED PAGE':'PROJECT NOTE' ?></span><h2><a href="<?= $workPath ?>/page/<?= e($projectPage['id']) ?>"><?= e($projectPage['title']) ?></a></h2><p class="work-page-excerpt"><?= e(mb_strimwidth($projectPage['body'],0,180,'…')) ?></p><p class="footnote">v<?= e($projectPage['version']) ?> · Updated <?= e($projectPage['updated_at']) ?></p></article><?php endforeach; ?></div><?php endif; ?>
<section class="card" id="work-new-page"><h2>Create a page</h2><form class="form-grid" method="post" action="<?= $workPath ?>/pages"><?= csrf_field() ?><label class="full">Title<input name="title" maxlength="200" required></label><label class="full">Page content<textarea name="body" maxlength="60000" rows="8" data-work-markdown></textarea></label><label class="work-checkbox full"><input type="checkbox" name="pinned" value="1"> Pin this page</label><div class="full"><button>Create page</button></div></form></section>
<?php $trashedPages=Db::all('SELECT * FROM work_pages WHERE project_id=? AND deleted_at IS NOT NULL ORDER BY deleted_at DESC',[$project['id']]);if($trashedPages): ?><details class="card"><summary>Page trash · <?= count($trashedPages) ?></summary><?php foreach($trashedPages as $projectPage): ?><article class="studio-record-row"><strong><?= e($projectPage['title']) ?></strong><form method="post" action="<?= $workPath ?>/page/<?= e($projectPage['id']) ?>/trash"><?= csrf_field() ?><input type="hidden" name="version" value="<?= e($projectPage['version']) ?>"><input type="hidden" name="restore" value="1"><button class="secondary">Restore page</button></form></article><?php endforeach; ?></details><?php endif; ?>
